import 'package:flutter/material.dart';
import '../core/app_controller.dart';
import '../core/json.dart';
import '../widgets/common.dart';
class FileStorageScreen extends StatefulWidget { const FileStorageScreen({required this.name, super.key}); final String name; @override State<FileStorageScreen> createState()=>_FileStorageScreenState(); }
class _FileStorageScreenState extends State<FileStorageScreen>{ List<JsonMap>? objects; String? error; bool busy=true; @override void initState(){super.initState();_load();} Future<void> _load() async {try{final d=await AppScope.of(context,listen:false).invoke('listStorageObjects',[widget.name,'']);if(mounted)setState(()=>objects=jsonList(d));}catch(e){if(mounted)setState(()=>error=e.toString());}finally{if(mounted)setState(()=>busy=false);}} @override Widget build(BuildContext c)=>Column(children:[Padding(padding:const EdgeInsets.fromLTRB(24,12,24,10),child:Row(children:[IconButton(tooltip:'返回',onPressed:()=>AppScope.of(c,listen:false).closeDetail(),icon:const Icon(Icons.arrow_back,size:19)),const SizedBox(width:8),Text('文件存储',style:Theme.of(c).textTheme.titleLarge),const SizedBox(width:10),Text(widget.name),const Spacer(),IconButton(tooltip:'刷新',onPressed:busy?null:_load,icon:const Icon(Icons.refresh,size:19))])),Expanded(child:busy?const BrandLoading():error!=null?ErrorBanner(message:error!):objects!.isEmpty?const EmptyState(icon:Icons.folder_open_outlined,title:'暂无文件'):ListView.separated(padding:const EdgeInsets.fromLTRB(24,4,24,24),itemCount:objects!.length,separatorBuilder:(_,_)=>const Divider(height:1),itemBuilder:(c,i){final o=objects![i];return ListTile(leading:const Icon(Icons.insert_drive_file_outlined),title:Text(stringValue(o['name'])),subtitle:Text('${intValue(o['size'])} bytes'),dense:true);}))]); }
